def solve(n):
    """Count primes strictly less than n using a fast bytearray sieve."""
    import math
    try:
        top = math.ceil(n) - 1  # largest integer p with p < n
    except (TypeError, ValueError):
        return 0
    if top < 2:
        return 0
    limit = top + 1
    sieve = bytearray([1]) * limit
    sieve[0] = sieve[1] = 0
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            step = i
            start = i * i
            sieve[start::step] = bytearray(len(range(start, limit, step)))
    return sum(sieve)

def solve(n: int) -> int:
    """Return the number of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes up to n-1.
    """
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start)//step + 1)
    return sum(sieve)

