def solve(lst):
    """Flatten a nested list of integers into a flat list preserving order.
    Uses an explicit stack of iterators to avoid recursion depth limits.
    """
    result = []
    # Stack of iterators, start with the top-level list
    stack = [iter(lst)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, list):
            # Dive into the nested list
            stack.append(iter(item))
        else:
            result.append(item)
    return result

