    """Simplify an absolute Unix file path.
    Resolve '.' and '..', collapse multiple slashes, and remove any trailing
    slash unless the result is the root '/' itself.
    """
    if not path:
        return '/'
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
    simplified = '/' + '/'.join(stack)
    return simplified if simplified != '' else '/'
