    Resolve '.' and '..', collapse multiple slashes, and remove any trailing slash
    unless the result is the root '/' itself.
    """
    # Split by '/', filter out empty and '.' parts
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
    simplified = '/' + '/'.join(stack)
    # Ensure root is '/'
    return simplified if simplified != '' else '/'

